            residue = key % period
            if residue in motif and motif[residue] != color:
                break
            motif[residue] = color
        else:
            if len(motif) == period:
                if direction == 1:
                    return [[motif[(r + c) % period] for c in range(w)] for r in range(h)]
                return [[motif[(c - r) % period] for c in range(w)] for r in range(h)]
    raise ValueError('clues do not determine a complete repeating stripe pattern')
"
}
